import { describe, expect, it } from 'vitest';
import type { Quat } from '../contracts/math';
import { Spinner } from './Spinner';
import { Windmill } from './Windmill';
import { TAU } from './rotation';
import type { ObstacleBodyHandle, ObstacleBodySpec, ObstaclePhysicsAdapter } from './types';

class RecordingBody implements ObstacleBodyHandle {
  readonly rotations: Quat[] = [];
  disposed = false;

  setNextRotation(rotation: Quat): void {
    this.rotations.push({ ...rotation });
  }

  dispose(): void {
    this.disposed = true;
  }
}

class RecordingPhysics implements ObstaclePhysicsAdapter {
  readonly specs: ObstacleBodySpec[] = [];
  readonly bodies: RecordingBody[] = [];

  createBody(spec: ObstacleBodySpec): ObstacleBodyHandle {
    this.specs.push(spec);
    const body = new RecordingBody();
    this.bodies.push(body);
    return body;
  }
}

function advance(obstacle: { update(deltaSeconds: number): void }, seconds: number): void {
  const delta = 1 / 60;
  const steps = Math.round(seconds / delta);
  for (let index = 0; index < steps; index += 1) obstacle.update(delta);
}

describe('Spinner configuration', () => {
  it('spreads arms evenly around the hub', () => {
    const spinner = new Spinner({ id: 'spinner', position: { x: 0, y: 0, z: 0 }, armCount: 3, armLength: 3 });

    expect(spinner.colliders).toHaveLength(3);
    spinner.colliders.forEach((collider, index) => {
      const angle = (TAU * index) / 3;
      expect(collider.halfExtents.x).toBeCloseTo(1.5, 10);
      expect(collider.offset.x).toBeCloseTo(Math.cos(angle) * 1.5, 10);
      expect(collider.offset.z).toBeCloseTo(-Math.sin(angle) * 1.5, 10);
      expect(collider.offset.y).toBe(0);
    });
  });

  it('requires at least two whole arms', () => {
    const position = { x: 0, y: 0, z: 0 };
    expect(() => new Spinner({ id: 'spinner', position, armCount: 1 })).toThrow(/at least 2/);
    expect(() => new Spinner({ id: 'spinner', position, armCount: 2.5 })).toThrow(/integer/);
  });

  it('rotates around the vertical axis', () => {
    const spinner = new Spinner({ id: 'spinner', position: { x: 0, y: 0, z: 0 }, speed: 1 });

    advance(spinner, 1);

    expect(spinner.angle).toBeCloseTo(1, 6);
    expect(spinner.rotation.y).toBeCloseTo(Math.sin(0.5), 6);
    expect(spinner.rotation.x).toBeCloseTo(0, 10);
  });
});

describe('Windmill configuration', () => {
  it('spins around the depth axis and keeps the tower static', () => {
    const physics = new RecordingPhysics();
    const windmill = new Windmill({
      id: 'windmill',
      position: { x: 0, y: 0, z: 0 },
      bladeCount: 4,
      bladeLength: 2,
      towerHeight: 3,
      speed: 2,
      physics,
    });

    expect(windmill.axis).toEqual({ x: 0, y: 0, z: 1 });
    expect(windmill.colliders).toHaveLength(4);
    expect(windmill.staticColliders).toHaveLength(1);
    expect(windmill.staticColliders[0].halfExtents.y).toBeCloseTo(1.5, 10);
    expect(windmill.staticColliders[0].offset.y).toBeCloseTo(-1.5, 10);

    expect(physics.specs).toHaveLength(2);
    expect(physics.specs[0].kind).toBe('kinematic');
    expect(physics.specs[1].kind).toBe('fixed');
    expect(physics.specs[1].id).toBe('windmill:static');

    advance(windmill, 0.5);

    expect(windmill.angle).toBeCloseTo(1, 6);
    expect(windmill.rotation.z).toBeCloseTo(Math.sin(0.5), 6);
    expect(windmill.rotation.y).toBeCloseTo(0, 10);

    windmill.dispose();
    expect(physics.bodies[0].disposed).toBe(true);
    expect(physics.bodies[1].disposed).toBe(true);
    expect(windmill.isDisposed).toBe(true);
  });

  it('places blades on a circle of half the blade length', () => {
    const windmill = new Windmill({ id: 'windmill', position: { x: 0, y: 0, z: 0 }, bladeCount: 3, bladeLength: 4 });

    windmill.colliders.forEach((collider) => {
      expect(Math.hypot(collider.offset.x, collider.offset.y)).toBeCloseTo(2, 10);
      expect(collider.offset.z).toBe(0);
    });
  });

  it('rejects invalid blade and tower configuration', () => {
    const position = { x: 0, y: 0, z: 0 };
    expect(() => new Windmill({ id: 'windmill', position, bladeCount: 1 })).toThrow(/at least 2/);
    expect(() => new Windmill({ id: 'windmill', position, towerHeight: 0 })).toThrow(/positive finite/);
  });
});
